from helpers import D, src, DSM, mk
from functools import partial
CARDS = []
X = partial(mk, "culture", "culture", "globe")
DSM_X = DSM("Culture and Psychiatric Diagnosis; Cultural Concepts of Distress")
CFI = src("src-cfi", "DSM-5 Cultural Formulation Interview and the evolution of cultural assessment in psychiatry", "Psychiatric Times", "https://www.psychiatrictimes.com/view/dsm-5-cultural-formulation-interview-and-evolution-cultural-assessment-psychiatry", seen=True)
FPR = src("src-fpr-culture", "DSM-5 on culture: a significant advance", "Foundation for Psychocultural Research", "https://thefpr.org/dsm-5-on-culture-a-significant-advance/", seen=True)
NLAAS = src("src-nlaas-ataque", "Ataque de nervios as a marker of social and psychiatric vulnerability: results from the NLAAS", "International Journal of Social Psychiatry (Guarnaccia et al.); PMC2865565", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2865565", 2010, seen=True)
KHYAL = src("src-khyal", "Khyâl attacks: a key syndrome of psychological distress among Cambodian populations", "Hinton et al.; khyalattack.com", "https://khyalattack.com/", seen=True)
TKS = src("src-tks-community", "Taijin kyofusho in a Japanese community population", "Transcultural Psychiatry", "https://www.ovid.com/journals/tpsy/pdf/10.1177/136346150103800408~taijin-kyofusho-in-a-japanese-community-population", 2001, seen=True, note="Not opened.")
DHAT = src("src-dhat", "Dhat syndrome in relation to demographic characteristics", "PubMed Central (PMC2918320)", "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC2918320/", seen=True, note="Not opened.")
FBENCH = src("src-friendship-bench", "The Friendship Bench", "Centre for Global Mental Health", "https://www.centreforglobalmentalhealth.org/research-projects/the-friendship-bench/", seen=True)
GEN_COMMS = ["nami-connection-and-helpline", "mind-side-by-side", "sane-forums-australia", "beyondblue-forums"]
X_NOTE = ["Cultural concepts are described respectfully, in their own terms, and never as 'exotic' or 'primitive'.", "Community reviewer from the relevant culture requested."]
CC_ISNOT = "Cultural concepts aren't DSM diagnoses and aren't 'wrong' versions of them. The same person may use both frameworks. "

def cc(tid, name, title, aka, one, simple, feel, signs, myths, how, helps, reach, isnot, hope, related, gloss, vis, srcs, qs=[], sens="standard", cult=None, extra_notes=[]):
    CARDS.append(X(tid, name, title, aka, "n/a (cultural concept of distress)", one, simple, feel, signs, myths, how, helps, reach, isnot, hope, related, gloss, GEN_COMMS, vis, srcs, qs=qs, sens=sens, notes=X_NOTE + extra_notes, clin=True, card_type="cultural-concept", cult=cult))

CARDS.append(X("culture-and-mental-health", "Culture and Mental Health", "How culture shapes distress, diagnosis, and care", ["cultural formulation", "cultural concepts of distress", "Cultural Formulation Interview (CFI)"], "n/a",
 "Culture shapes how distress is felt, described, explained, and treated. Good care asks about it directly.",
 "Everyone has culture: shared ideas about what a good life looks like, what counts as a problem, how to talk about feelings, and where to turn for help. Culture shapes whether distress shows up as sadness, body pain, spirit trouble, or 'thinking too much'. The DSM includes a Cultural Formulation Interview, 16 questions about a person's own view of their problem, and a glossary of cultural concepts of distress, nine of which have cards here. Diagnosis with culture fits.",
 ["My doctor asked 'what do you call this problem, and what do people in your family think causes it?' Nobody had ever asked. The answer changed the treatment.", "In my language there's no word for depression. There is a word for a heart that has become heavy. That's the word I needed someone to understand."],
 ["Distress described through the body, spirits, family, or 'thinking too much' rather than mood words", "Explanations involving stress, loss, spiritual causes, or social problems", "Help sought from family, faith, traditional healers, and clinics, often together", "Mistrust of services based on past experience or discrimination", "Interpreters or bicultural workers making the difference between being heard and not"],
 [{"myth": "Culture only matters for 'other' people.", "fact": "Everyone's distress is shaped by culture, including the culture of the clinician and the DSM itself. The CFI is designed for every patient."},
  {"myth": "Cultural concepts are old-fashioned beliefs to be corrected.", "fact": "They're coherent ways of understanding suffering, often with their own effective supports. Good care works with them, not against them."},
  {"myth": "Using an interpreter makes therapy impossible.", "fact": "Professional interpreters and bicultural workers make therapy possible and effective. Family members as interpreters are what to avoid."}],
 {"plain": "Culture matters for everyone, so there's no prevalence. Migrants, refugees, and minority groups face extra barriers to care in every country covered.", "figure": "n/a", "source_ref": "src-dsm"},
 {"plain_summary": "The Cultural Formulation Interview helps clinicians understand how a person and their community see the problem, what they think causes it, what's helped, and what they want from care. Culturally adapted therapies, bicultural workers, professional interpreters, and collaboration with faith and community leaders improve engagement and outcomes. Community-based approaches like Zimbabwe's Friendship Bench, where trained lay health workers deliver problem-solving therapy on a bench outside a clinic, show that care can be built from local concepts rather than imported.",
  "evidence_based_options": ["Cultural Formulation Interview as part of assessment", "Culturally adapted psychotherapies and bicultural clinicians", "Professional interpreters, never family members", "Community and lay-worker models such as the Friendship Bench; collaboration with faith and community leaders"],
  "self_help_that_supports_care": ["Telling a clinician what you call the problem and what your family thinks causes it", "Asking for an interpreter or a clinician who understands your background", "Using the supports your community already has, alongside clinical care", "Reading the nine cultural concept cards if one sounds familiar"],
  "guideline_refs": ["src-cfi"]},
 "If you feel a clinician doesn't understand your background, you can say so and ask for the Cultural Formulation Interview, an interpreter, or a different clinician. Community organisations for your culture or faith can help you find care that fits. If you're in crisis, the crisis strip lists services in many languages.",
 "Culture isn't a diagnosis, and a cultural concept isn't a 'wrong' version of a DSM one. Many people use both frameworks at once.",
 "When care fits a person's culture, people who'd given up on services come back, and treatments that 'didn't work' start working.",
 ["social-environment-and-identity-stress", "ataque-de-nervios", "kufungisisa", "taijin-kyofusho", "somatic-symptom-disorder", "when-it-doesnt-fit-a-label"],
 ["stigma", "formulation", "lived-experience", "peer-support", "assessment"],
 GEN_COMMS, ("Soft line illustration of a clinician and a person talking on a bench outside a clinic, an interpreter beside them, trees and a market in the background. Pastel earth tones and sky blue.", "A clinician and a person talk on a bench outside a clinic with an interpreter beside them."),
 [DSM_X, CFI, FPR, FBENCH], notes=X_NOTE, card_type="explainer", clin=True))

cc("ataque-de-nervios", "Ataque de Nervios", "An 'attack of nerves' in Latino communities", ["attack of nerves"],
 "An intense episode of distress, often after a family upset, with crying, shouting, shaking, or heat rising in the chest.",
 "Ataque de nervios is a way of expressing overwhelming distress recognised across many Latino communities. An episode usually follows a family stress, such as news of a death, and involves uncontrollable crying or shouting, trembling, heat rising from the chest, and sometimes fainting, with little memory afterwards. The community sees it as a response to upset, not madness. It overlaps with panic attacks but has a clear trigger. Family support and treatment of underlying anxiety or depression help.",
 ["When my mother got the call about my brother, she screamed, shook, and went down. Nobody called an ambulance; the family held her. That's an ataque.", "My doctor called it a panic attack. My grandmother called it nervios. The treatment that worked respected both."],
 ["Sudden intense crying, shouting, trembling, or heat rising in the chest after a family upset", "Sometimes fainting, aggression, or dissociation", "Often little memory of the episode afterwards", "Usually a clear trigger; no lasting fear of the next one", "Understood as a response to stress, with family support expected"],
 [{"myth": "An ataque is just hysteria.", "fact": "It's a recognised, culturally shared way of expressing acute distress, often protective because it brings family support immediately."},
  {"myth": "It's the same as a panic attack.", "fact": "They overlap, but an ataque usually has a clear trigger and isn't followed by dread of the next one. The distinction matters for treatment."}],
 {"plain": "In a large US survey, between 7 and 15 in 100 Latino adults reported having had an ataque, highest among Puerto Ricans. People who report them are more likely to have anxiety, depression, or substance problems.", "figure": "7%–15% lifetime across Latino groups in the National Latino and Asian American Study (N=2,554), highest among Puerto Ricans", "source_ref": "src-nlaas-ataque"},
 {"plain_summary": "Many episodes need no treatment beyond family care. When ataques are frequent or there's underlying anxiety, depression, trauma, or panic disorder, the usual treatments for those conditions, especially culturally adapted CBT and family involvement, help, with any medication prescribed and monitored by a doctor. Clinicians should ask what the person and family call the episodes and what they think caused them.",
  "evidence_based_options": ["Assessment using the Cultural Formulation Interview", "Culturally adapted CBT for anxiety, panic, or depression where present", "Family involvement in care", "Treatment of underlying trauma or substance use"],
  "self_help_that_supports_care": ["Telling clinicians about ataques in your own words", "Family and community support after episodes", "Noticing patterns of stress that trigger episodes", "Help for the underlying worry or grief"],
  "guideline_refs": ["src-nlaas-ataque"]},
 "If ataques are frequent, come without a trigger, or sit alongside ongoing anxiety or low mood, see a doctor or therapist and describe them as ataques. Seek urgent care for chest pain or fainting that doesn't resolve, to rule out medical causes.",
 CC_ISNOT + "Seizures and heart problems can look similar and are ruled out medically.",
 "Ataques are understood by the people around you, and the distress behind them can be eased.",
 ["panic-disorder", "culture-and-mental-health", "nervios", "acute-stress-disorder", "major-depressive-disorder"],
 ["panic-attack", "dissociation", "stress", "support-system"],
 ("Soft line illustration of a family gathered around a woman on a sofa, holding her hands, a glass of water on the table, warm evening light. Pastel terracotta and sky blue.", "A family gathers around a woman on a sofa, holding her hands."),
 [DSM_X, NLAAS], sens="elevated")

cc("dhat-syndrome", "Dhat Syndrome", "Distress about losing semen, in South Asia", ["dhat", "semen-loss anxiety", "jiryan"],
 "Anxiety, weakness, and low mood attributed to losing semen, recognised across South Asia.",
 "Dhat syndrome is a way of experiencing distress found across South Asia and among South Asian communities elsewhere. A man, and sometimes a woman, attributes fatigue, weakness, anxiety, low mood, or sexual difficulties to the loss of 'dhat', a vital fluid, through urine or emissions. The belief draws on traditional ideas about semen as a source of vitality. The suffering is real and often reflects depression, anxiety, or sexual worry. Treatment that respects the explanation works well.",
 ["I was sure I was wasting away. The doctor didn't laugh. He explained the body, treated the depression, and the weakness went.", "Every clinic in my town sees this. Some sell expensive 'cures'. The honest doctors talk about anxiety."],
 ["Fatigue, weakness, or low energy attributed to loss of semen", "Anxiety, guilt, or low mood, often with sexual worry", "Concern about a whitish discharge in urine", "Seeking help from many clinics, sometimes being sold unproven remedies"],
 [{"myth": "It's a sign of ignorance.", "fact": "It reflects a coherent traditional understanding of the body, shared by many educated people. The distress deserves respect and treatment."},
  {"myth": "Nothing is actually wrong.", "fact": "Depression, anxiety, and sexual difficulties are very common underneath, and treating them resolves the 'weakness'."}],
 {"plain": "Dhat syndrome is common in sexual health and primary care clinics across South Asia, though population figures are lacking. One study found it in about 1 in 8 men with depression.", "figure": "Prevalence not established in the general population; 12.9% among men with depression in one 2026 study; majority of psychosexual clinic patients in some reports", "source_ref": "src-dhat", "note": "Clinic-based figures only."},
 {"plain_summary": "The most effective approach combines respectful education about the body, reassurance that the discharge is harmless, and treatment of underlying depression, anxiety, or sexual dysfunction with counselling or CBT, and medication where needed, prescribed and monitored by a doctor. Dismissing the belief tends to push people toward unregulated practitioners. Clinicians trained in culturally sensitive sexual health do best.",
  "evidence_based_options": ["Culturally respectful psychoeducation about the body", "CBT or counselling for anxiety and sexual worry", "Treatment of depression or sexual dysfunction, with any medication prescribed and monitored by a doctor", "Avoiding unproven or expensive 'cures'"],
  "self_help_that_supports_care": ["Seeing a qualified doctor or psychologist rather than a roadside clinic", "Learning about normal bodily functions from reputable sources", "Treating low mood and sleep as problems in their own right", "Talking openly with a clinician who understands the concept"],
  "guideline_refs": []},
 "If weakness, anxiety, or low mood attributed to semen loss is affecting your life, see a qualified doctor or mental health professional, and name the concern directly. Be cautious of anyone offering expensive cures.",
 CC_ISNOT + "Genuine urinary or sexual health conditions are checked by a doctor.",
 "With respectful care, the weakness lifts, the worry eases, and people get their energy and confidence back.",
 ["major-depressive-disorder", "generalized-anxiety-disorder", "somatic-symptom-disorder", "erectile-disorder", "culture-and-mental-health"],
 ["somatic-symptoms", "stress", "psychoeducation", "gp-primary-care"],
 ("Soft line illustration of a young man talking with a doctor in a clinic with a window onto a busy street, a poster of the human body on the wall, daylight. Pastel saffron and sky blue.", "A young man talks with a doctor in a clinic with a window onto a busy street."),
 [DSM_X, DHAT], sens="elevated")

cc("khyal-cap", "Khyâl Cap", "'Wind attacks' in Cambodian communities", ["khyal attack", "wind overload", "kyol goeu"],
 "Panic-like episodes understood as 'wind' rising in the body, common among Cambodians, often linked to trauma.",
 "Khyâl cap, or 'wind attack', is a Cambodian way of understanding sudden episodes of dizziness, palpitations, breathlessness, cold hands, neck soreness, and fear. Khyâl, a wind-like substance, is believed to rise in the body and cause fainting, blurred vision, or even death if it surges. Episodes overlap with panic attacks and are especially common among survivors of the Khmer Rouge era, where trauma and these fears intertwine. Treatment that respects the explanation and addresses panic and trauma works.",
 ["When I stand up fast, the khyâl rises and I think I will die. The clinic that understood this helped me more than any that didn't.", "My mother coins her neck to release the wind. The therapist asked about it instead of telling her to stop."],
 ["Sudden dizziness, palpitations, breathlessness, cold hands, or neck soreness", "Fear that the 'wind' will cause fainting, blindness, or death", "Often triggered by standing up, worry, or trauma reminders", "Self-treatment with coining or cupping to release wind", "Common among survivors of war and trauma"],
 [{"myth": "Coining and cupping marks are signs of abuse.", "fact": "They're traditional treatments for khyâl and other illnesses, widely used and usually harmless. Clinicians should ask, not assume."},
  {"myth": "It's just a panic attack with a different name.", "fact": "The overlap is real, but the fear of catastrophe from wind, and the link to trauma, shape how it's experienced and what helps."}],
 {"plain": "Among Cambodian refugees attending psychiatric clinics, panic and khyâl-related episodes are very common; population figures aren't available.", "figure": "60% of 89 Khmer refugees at two clinics had current panic disorder (2000 study); population prevalence not established", "source_ref": "src-khyal", "note": "Clinic-based figures only."},
 {"plain_summary": "Culturally adapted CBT developed specifically for Cambodian refugees, which explains the body's stress response in terms that respect ideas about wind and includes trauma treatment, has good evidence. Treating PTSD and panic disorder, with any medication prescribed and monitored by a doctor, reduces episodes. Working with, not against, traditional practices like coining builds trust.",
  "evidence_based_options": ["Culturally adapted CBT for panic and trauma in Cambodian communities", "Treatment of PTSD and panic disorder", "Interpreters and bicultural clinicians", "Respectful integration of traditional practices"],
  "self_help_that_supports_care": ["Describing the wind episodes to a clinician in your own terms", "Slow breathing and grounding during episodes", "Community and temple support", "Help for trauma memories, when ready"],
  "guideline_refs": ["src-khyal"]},
 "If wind attacks are frequent, frightening, or linked to memories of the past, ask for a clinician who works with Cambodian communities or for an interpreter. Seek urgent care for chest pain or fainting that doesn't settle.",
 CC_ISNOT + "Heart and blood pressure conditions are checked by a doctor.",
 "Communities that survived the unimaginable have found care that honours both the wind and the wound. Episodes become rarer and less frightening.",
 ["panic-disorder", "posttraumatic-stress-disorder", "culture-and-mental-health", "ataque-de-nervios"],
 ["panic-attack", "trauma", "hypervigilance", "grounding"],
 ("Soft line illustration of an older Cambodian woman and a younger relative sitting under a tree outside a temple, a community worker nearby, soft light. Pastel jade and sky blue.", "An older woman and a younger relative sit under a tree outside a temple with a community worker nearby."),
 [DSM_X, KHYAL], sens="elevated")

cc("kufungisisa", "Kufungisisa", "'Thinking too much', in Zimbabwe and beyond", ["thinking too much", "excessive thinking"],
 "A Shona term for 'thinking too much', used for both the cause and the experience of depression and anxiety.",
 "Kufungisisa, Shona for 'thinking too much', is how many people in Zimbabwe, and in similar terms elsewhere, describe what clinicians might call depression or anxiety. It's both a cause (thinking too much makes you ill) and the experience itself: ruminating, worry, headaches, sleeplessness, and a heavy heart, often brought on by poverty, loss, or family trouble. It's known worldwide because of the Friendship Bench, where trained grandmothers deliver problem-solving therapy on benches outside clinics, with strong trial results.",
 ["The grandmother on the bench didn't ask about symptoms. She asked what I was thinking too much about. Then we solved one thing at a time.", "In my language we don't say depression. We say the person is thinking too much. Everyone knows what that means."],
 ["Ruminating and worrying that won't stop", "Headaches, sleeplessness, tiredness, a heavy heart", "Brought on by poverty, loss, illness, or family problems", "Withdrawing, losing interest, not managing daily tasks"],
 [{"myth": "'Thinking too much' is too vague to treat.", "fact": "It's specific enough that a trial of problem-solving therapy for kufungisisa, delivered by lay health workers, cut depression and anxiety substantially."},
  {"myth": "It's a weaker version of real depression.", "fact": "It's the same suffering described in local terms, and local terms are what make help acceptable and effective."}],
 {"plain": "'Thinking too much' idioms are found in dozens of cultures. In Zimbabwe, kufungisisa is among the most common presentations in primary care; exact figures depend on how it's measured.", "figure": "Prevalence not established; common in Zimbabwean primary care and the basis of the Friendship Bench trial", "source_ref": "src-friendship-bench"},
 {"plain_summary": "The Friendship Bench model, problem-solving therapy delivered by trained lay health workers on a bench outside a clinic, with peer support groups and referral for severe cases, has strong evidence and has spread to several countries. Standard treatments for depression and anxiety also apply, including CBT and, where needed, medication prescribed and monitored by a doctor. Addressing the practical problems, such as money, food, and illness, is part of the therapy, not separate from it.",
  "evidence_based_options": ["Problem-solving therapy delivered by trained lay or community health workers (Friendship Bench)", "Peer support groups", "CBT or other therapy for depression and anxiety", "Referral and medication for severe depression, prescribed and monitored by a doctor"],
  "self_help_that_supports_care": ["Naming what you're thinking too much about", "Breaking one problem into a first step", "Talking to a trusted elder or community worker", "Sleep, food, and connection, even when hard"],
  "guideline_refs": ["src-friendship-bench"]},
 "If you're thinking too much and it's affecting your sleep, energy, or ability to manage, talk to a community health worker, a Friendship Bench if one is near, a doctor, or a counsellor. If you're thinking about ending your life, reach out to a crisis line or someone you trust now.",
 CC_ISNOT + "Ordinary worry that passes isn't kufungisisa; it's the persistence and the weight that matter.",
 "Grandmothers on benches have helped tens of thousands of people stop thinking too much. The model is simple because the problem is human.",
 ["major-depressive-disorder", "generalized-anxiety-disorder", "culture-and-mental-health", "housing-and-money-problems", "shenjing-shuairuo"],
 ["rumination", "stress", "peer-support", "lived-experience"],
 ("Soft line illustration of an older woman and a younger person sitting on a wooden bench under a tree outside a small clinic, talking, warm light. Pastel ochre and sky blue.", "An older woman and a younger person talk on a wooden bench under a tree outside a clinic."),
 [DSM_X, FBENCH], sens="elevated")

cc("maladi-moun", "Maladi Moun", "'Humanly caused illness' in Haitian communities", ["sent sickness", "maladi moun", "humanly caused illness"],
 "A Haitian explanation for illness, including mental distress, as sent by another person through envy or ill will.",
 "Maladi moun, 'humanly caused illness' or 'sent sickness', is a Haitian way of explaining illness, including depression, psychosis, academic or social failure, and physical disease, as caused by another person's envy, hatred, or sorcery. Success or good fortune can make a person a target. It sits alongside biological and spiritual explanations, and people often seek care from doctors, churches, and Vodou practitioners at once. Understanding it helps clinicians build trust and avoid mislabelling cultural beliefs as delusions.",
 ["When my son became ill after his promotion, the family said someone had sent it. The psychiatrist listened, and then treated the psychosis. Both things happened.", "Being asked whether I thought someone had caused my illness, without judgement, was the first time I trusted a doctor here."],
 ["Illness or misfortune explained as sent by another person's envy or ill will", "Often following success, a promotion, or good fortune", "Care sought from doctors, churches, and traditional practitioners together", "Fear, mistrust, or shame about the cause"],
 [{"myth": "Believing illness was sent by someone is a delusion.", "fact": "It's a shared cultural explanation, not a personal fixed false belief. The Cultural Formulation Interview helps clinicians tell the difference."},
  {"myth": "People who believe this won't accept medical treatment.", "fact": "Most use several kinds of help at once. Respecting the explanation makes medical and psychological care more likely to be accepted."}],
 {"plain": "Maladi moun is a widely shared explanation in Haitian communities; there's no prevalence figure for a way of explaining illness.", "figure": "n/a", "source_ref": "src-dsm"},
 {"plain_summary": "Care works best when clinicians ask about the person's and family's explanation, respect it, and treat the underlying condition, whether depression, psychosis, or anxiety, with standard therapy and, where needed, medication prescribed and monitored by a doctor. Collaboration with churches and community leaders, and Haitian Creole interpreters or bicultural workers, improve trust. Distinguishing shared belief from delusion requires cultural knowledge.",
  "evidence_based_options": ["Cultural Formulation Interview", "Treatment of the underlying condition with therapy and, where needed, medication prescribed and monitored by a doctor", "Haitian Creole interpreters and bicultural clinicians", "Collaboration with faith and community leaders"],
  "self_help_that_supports_care": ["Telling clinicians what your family believes caused the illness", "Using church, community, and medical help together", "Finding a clinician who knows Haitian culture", "Support for the fear and isolation the explanation can bring"],
  "guideline_refs": ["src-cfi"]},
 "If you or a family member is unwell and the family believes it was sent, you can still get medical and psychological help, and you can tell the clinician what you believe. If someone is hearing voices, very confused, or at risk, seek urgent care.",
 CC_ISNOT + "A shared cultural belief is not a delusion; a belief that is unique, fixed, and out of step with the person's own community may be.",
 "Families that hold both explanations get both kinds of help. Illness that was 'sent' still gets better.",
 ["culture-and-mental-health", "schizophrenia", "major-depressive-disorder", "social-environment-and-identity-stress"],
 ["delusion", "formulation", "stigma", "support-system"],
 ("Soft line illustration of a family in a sunlit living room with a visiting nurse and a pastor, a cup of coffee on the table, plants in the window. Pastel coral and sky blue.", "A family sits in a sunlit living room with a visiting nurse and a pastor."),
 [DSM_X, FPR, CFI])

cc("nervios", "Nervios", "'Nerves': a Latino way of talking about distress", ["nerves", "padecer de los nervios"],
 "A common Latino idiom for vulnerability to stress and a range of distress: worry, tearfulness, headaches, poor sleep.",
 "Nervios, 'nerves', is a widely used idiom across Latin America and Latino communities for a general vulnerability to life's stresses and for the distress itself: headaches, irritability, stomach trouble, poor sleep, nervousness, tearfulness, and feeling easily overwhelmed. Someone may have nervios for years, as a trait, or an episode after a hard time. It overlaps with anxiety and depression but is broader and less stigmatised. Clinicians who ask about nervios get a fuller picture.",
 ["My abuela always said she had nervios. Now I understand she was anxious and depressed for fifty years and nobody treated it.", "Saying I have nervios is easy. Saying I have anxiety still feels like admitting something is wrong with me."],
 ["Headaches, stomach trouble, trembling, or poor sleep under stress", "Irritability, tearfulness, nervousness, or feeling overwhelmed", "Difficulty concentrating", "May be long-standing (a trait) or an episode after hard times", "A less stigmatised way of describing anxiety or low mood"],
 [{"myth": "Nervios is just a folk word for anxiety.", "fact": "It covers more: a sense of vulnerability, bodily symptoms, and social stress. Asking about it opens conversations that 'anxiety' may close."},
  {"myth": "If it's cultural, it doesn't need treatment.", "fact": "Chronic nervios often reflects untreated anxiety or depression, and treatment helps."}],
 {"plain": "Nervios is extremely common as an idiom; most Latino adults would recognise it. There's no prevalence figure for a way of speaking.", "figure": "n/a", "source_ref": "src-dsm"},
 {"plain_summary": "Treatment matches what's underneath: CBT or other therapy for anxiety and depression, stress management, treatment of sleep problems, and, where needed, medication prescribed and monitored by a doctor. Culturally adapted programmes in Spanish, family involvement, and addressing the social stresses, such as money, migration, or discrimination, improve results. Primary care is often the first and best place to raise it.",
  "evidence_based_options": ["Assessment that asks about nervios and its triggers", "CBT or counselling for anxiety and depression, in Spanish where needed", "Stress management and sleep treatment", "Addressing social stresses alongside clinical care"],
  "self_help_that_supports_care": ["Telling a doctor 'I have nervios' and describing the symptoms", "Family and community support", "Sleep, movement, and limiting caffeine", "Help for the practical stresses behind the nerves"],
  "guideline_refs": []},
 "If nervios are constant, keeping you from sleeping or coping, or getting worse, talk to a doctor or counsellor and use the word you'd use at home. If you're thinking about ending your life, use the crisis strip now.",
 CC_ISNOT + "An ataque de nervios is a sudden episode; nervios is the ongoing state. Both have cards.",
 "Treating the nerves that families have carried for generations is possible, and often starts with one honest conversation in the right language.",
 ["generalized-anxiety-disorder", "major-depressive-disorder", "ataque-de-nervios", "somatic-symptom-disorder", "culture-and-mental-health"],
 ["stress", "somatic-symptoms", "irritability", "gp-primary-care"],
 ("Soft line illustration of three generations of a family on a porch, the grandmother with a cup of tea, a younger woman with a notebook, evening light. Pastel rose and sky blue.", "Three generations of a family sit together on a porch in evening light."),
 [DSM_X, NLAAS])

cc("shenjing-shuairuo", "Shenjing Shuairuo", "'Weakness of the nervous system', in Chinese communities", ["neurasthenia", "shenjing shuairuo"],
 "A Chinese concept of nervous weakness: fatigue, poor concentration, sleep trouble, aches, and low mood.",
 "Shenjing shuairuo, 'weakness of the nervous system', is a Chinese concept close to the older Western diagnosis of neurasthenia. It brings together mental and physical fatigue, poor memory and concentration, irritability, sleep problems, headaches, dizziness, and aches, understood as the result of overwork, stress, or imbalance in the body's energy. It was long more acceptable than 'depression' in China, and many people diagnosed with it meet criteria for depression or anxiety. It's still used by many families.",
 ["My father never said he was depressed. He said his nerves were weak from working too hard. The doctor who used his words got him to accept treatment.", "The traditional medicine doctor and the psychiatrist agreed more than they disagreed. Rest, herbs, and an antidepressant."],
 ["Mental and physical exhaustion that rest doesn't fix", "Poor memory and concentration; irritability", "Trouble sleeping, headaches, dizziness, aches", "Understood as weakness from overwork or imbalance", "Often meets criteria for depression or anxiety"],
 [{"myth": "Neurasthenia is an outdated label with no meaning.", "fact": "In Chinese medicine and communities it remains a meaningful way of describing real exhaustion and distress, and a bridge to care."},
  {"myth": "People who use this term are hiding their depression.", "fact": "They're describing it in the terms their culture offers. Working within those terms is how treatment gets accepted."}],
 {"plain": "Shenjing shuairuo was once among the most common diagnoses in Chinese clinics; its use has declined as depression became more accepted, but it remains common in communities and traditional medicine.", "figure": "n/a", "source_ref": "src-dsm"},
 {"plain_summary": "Treatment addresses the underlying depression, anxiety, insomnia, or burnout: therapy, sleep treatment, stress and work changes, and, where needed, medication prescribed and monitored by a doctor. Many people combine this with traditional Chinese medicine, rest, and diet, and clinicians do best by respecting that rather than dismissing it. Using the person's own words improves acceptance of care.",
  "evidence_based_options": ["Assessment that respects the concept and checks for depression, anxiety, and insomnia", "Therapy such as CBT; sleep treatment", "Medication for depression or anxiety where needed, prescribed and monitored by a doctor", "Work and stress changes; integration with traditional practices the person values"],
  "self_help_that_supports_care": ["Describing the exhaustion in your own terms to a clinician", "Rest and reduced overwork, where possible", "Sleep routine and movement", "Family support and reduced pressure"],
  "guideline_refs": []},
 "If exhaustion, poor concentration, and sleep trouble are persistent, see a doctor and describe them as you understand them. Depression and anxiety are treatable, whatever they're called. If you're thinking about ending your life, use the crisis strip now.",
 CC_ISNOT + "Thyroid, anaemia, and other medical causes of fatigue are checked by a doctor.",
 "Weak nerves grow strong again. People who'd never have said 'depression' recover when care meets them in their own language.",
 ["major-depressive-disorder", "generalized-anxiety-disorder", "insomnia-disorder", "somatic-symptom-disorder", "kufungisisa", "culture-and-mental-health"],
 ["burnout", "brain-fog", "somatic-symptoms", "stress"],
 ("Soft line illustration of a man resting in a chair by a window with a cup of tea, a bowl of soup, and a family member reading nearby, soft light. Pastel jade and cream.", "A man rests in a chair by a window with tea and soup while a family member reads nearby."),
 [DSM_X, FPR])

cc("susto", "Susto", "'Fright' or soul loss, in Latin American communities", ["fright", "espanto", "soul loss"],
 "An illness following a frightening event, understood as the soul leaving the body, with sadness, poor appetite, and sleep trouble.",
 "Susto, 'fright', is a Latin American explanation for illness that follows a frightening event. The soul is believed to leave the body, leaving the person unhappy, sick, and struggling: poor appetite and sleep, sadness, low energy, lack of motivation, feelings of worthlessness, and body aches. Symptoms may appear days or years after the fright. Ritual healings aim to call the soul back. Susto overlaps with depression and PTSD, and research links it to higher rates of both.",
 ["After the accident my aunt said I had susto. The curandera did the limpia, and I also saw a counsellor. Both helped me come back to myself.", "I didn't have words for what the robbery did to me. Susto was the word my community had, and it fit."],
 ["Sadness, low energy, poor appetite, and sleep trouble after a frightening event", "Feeling the self has gone; lack of motivation or worth", "Body aches, headaches, stomach trouble", "Symptoms appearing soon after or years later", "Healing sought through ritual as well as clinics"],
 [{"myth": "Susto is superstition.", "fact": "It's a coherent way of describing the aftermath of trauma and shock, with its own healing practices. It maps closely onto conditions clinicians recognise."},
  {"myth": "A ritual healing is all that's needed.", "fact": "Ritual healing can be meaningful and helpful. When symptoms persist, treatment for depression or trauma adds to it."}],
 {"plain": "Susto is widely recognised across Latin America; studies link it to higher rates of depression and PTSD, but general prevalence figures aren't available.", "figure": "n/a", "source_ref": "src-dsm"},
 {"plain_summary": "Care that respects susto as the person's explanation, asks about the frightening event, and treats what's there, often depression, PTSD, or an adjustment reaction, works best. Trauma-focused therapy, culturally adapted CBT, and, where needed, medication prescribed and monitored by a doctor are combined with the healing practices the person values. Clinicians should ask whether a curandero or healer is involved and work alongside.",
  "evidence_based_options": ["Cultural Formulation Interview and assessment for depression and PTSD", "Trauma-focused or culturally adapted therapy", "Medication for depression where needed, prescribed and monitored by a doctor", "Collaboration with traditional healers the person trusts"],
  "self_help_that_supports_care": ["Naming the fright and telling someone what happened", "Using community healing alongside clinical help", "Sleep, food, and gentle routine while the soul 'returns'", "Trauma support if memories keep intruding"],
  "guideline_refs": ["src-cfi"]},
 "If sadness, exhaustion, or body symptoms after a fright are lasting, see a doctor or counsellor and tell them about the susto. If memories of the event keep intruding, trauma therapy helps. If you're thinking about ending your life, use the crisis strip now.",
 CC_ISNOT + "Medical causes of fatigue and appetite loss are checked.",
 "The soul comes back. People recover from susto with community, ritual, and care, in whatever combination fits them.",
 ["posttraumatic-stress-disorder", "major-depressive-disorder", "adjustment-disorders", "culture-and-mental-health", "nervios"],
 ["trauma", "grief", "somatic-symptoms", "support-system"],
 ("Soft line illustration of a person sitting in a garden with an older healer offering a cup of herbal tea, marigolds in bloom, afternoon light. Pastel marigold and sky blue.", "A person sits in a garden as an older healer offers a cup of herbal tea among marigolds."),
 [DSM_X, FPR, CFI], sens="elevated")

cc("taijin-kyofusho", "Taijin Kyofusho", "Fear of offending others with your presence, in Japan", ["TKS", "anthropophobia", "interpersonal fear"],
 "Intense fear that your appearance, gaze, smell, or expressions will offend or embarrass others, recognised in Japan and Korea.",
 "Taijin kyofusho, roughly 'interpersonal fear', is a Japanese concept, with a Korean equivalent, for intense anxiety about offending or embarrassing others through your body: your gaze, blushing, odour, or expression. It overlaps with social anxiety disorder, but the focus is on harm done to others rather than embarrassment to oneself, reflecting cultural emphasis on group harmony. Some people are convinced they cause offence; others know the fear is excessive. It begins in adolescence and responds to therapy.",
 ["I was sure my eyes made people uncomfortable, so I never looked at anyone. The therapist understood it wasn't about me being judged. It was about me hurting them.", "In Japan it has a name and a history. Here they just called it social anxiety, which was close but not quite it."],
 ["Intense fear that your gaze, blushing, smell, or expression offends others", "Avoiding eye contact, social situations, or going out", "Focus on the discomfort caused to others, more than on being judged", "Begins in adolescence; may be mild or fixed", "Overlaps with social anxiety and sometimes with body dysmorphic concerns"],
 [{"myth": "It's just social anxiety with a Japanese name.", "fact": "The focus on harming others rather than being judged shapes the experience and the therapy. Recognising the difference matters."},
  {"myth": "It only occurs in Japan.", "fact": "Similar fears are reported in Korea and increasingly recognised elsewhere. Culture shapes the form, not the possibility."}],
 {"plain": "In one small Japanese community study, around 7 in 100 adults reported taijin kyofu symptoms; estimates in other sources range widely. Young adults in Japan report higher levels than in England.", "figure": "6.8% (9 of 132) with symptoms in one community sample (2001); lifetime estimates cited at 3%–13% in secondary sources", "source_ref": "src-tks-community", "note": "Small samples; confirm against primary sources."},
 {"plain_summary": "CBT adapted for taijin kyofusho, including exposure to feared situations and work on beliefs about causing offence, is effective, as are Japanese approaches such as Morita therapy, which emphasises accepting feelings and acting anyway. Medication used for social anxiety, prescribed and monitored by a doctor, helps some people. Where the belief of causing offence is fixed, treatment is adjusted accordingly.",
  "evidence_based_options": ["CBT adapted for interpersonal fear, including exposure", "Morita therapy and acceptance-based approaches", "Medication as for social anxiety where needed, prescribed and monitored by a doctor", "Assessment of co-occurring body dysmorphic or delusional features"],
  "self_help_that_supports_care": ["Testing the belief that others are offended by gently gathering evidence", "Gradual return to feared situations", "Not avoiding eye contact entirely; small steps", "Peer support with others who have social anxiety"],
  "guideline_refs": []},
 "If fear of offending others with your appearance or presence is keeping you from school, work, or relationships, talk to a doctor or therapist and describe it in these terms. If you're thinking about ending your life, use the crisis strip now.",
 CC_ISNOT + "Ordinary consideration for others, and cultural politeness, aren't a disorder.",
 "People who feared their very presence offended others find themselves at the table, looking people in the eye, and welcomed.",
 ["social-anxiety-disorder", "body-dysmorphic-disorder", "avoidant-personality-disorder", "culture-and-mental-health"],
 ["shyness-vs-social-anxiety", "avoidance", "exposure-therapy", "hikikomori"],
 ("Soft line illustration of two colleagues sharing lunch on a bench in a Japanese park under cherry blossom, relaxed eye contact, spring light. Pastel sakura pink and sky blue.", "Two colleagues share lunch on a park bench under cherry blossom."),
 [DSM_X, TKS], sens="elevated")
